def reverse_string(s):
    n = len(s)
    reversed_s = [None] * n                     # a brand new array to hold the reversed order
    for i in range(n):
        reversed_s[i] = s[n - 1 - i]               # walk the original array back to front
    for i in range(n):
        s[i] = reversed_s[i]                       # copy the reversed values back into the original


if __name__ == "__main__":
    s = ["h", "e", "l", "l", "o"]
    reverse_string(s)
    print("".join(s))

