import java.util.*;

public class Main {
    void reverseString(char[] s) {
        int n = s.length;
        char[] reversed = new char[n];                // a brand new array to hold the reversed order
        for (int i = 0; i < n; i++) {
            reversed[i] = s[n - 1 - i];                   // walk the original array back to front
        }
        for (int i = 0; i < n; i++) {
            s[i] = reversed[i];                           // copy the reversed values back into the original
        }
    }

    public static void main(String[] args) {
        char[] s = {'h', 'e', 'l', 'l', 'o'};
        Main solution = new Main();
        solution.reverseString(s);
        System.out.println(new String(s));
    }
}

